{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SNITCH_SIZE_CHANNEL_CUTSIZE AS WITH source_inventory AS ( SELECT * FROM SNITCH_DB.MAPLEMONK.SNITCH_SIZE_CHANNEL_INVENTORY ), size_level AS ( SELECT SKU_GROUP, \'ALL WAREHOUSES\' AS WAREHOUSE, \'40/3XL\' AS SIZE_LABEL, CATEGORY_NAME, COALESCE(\"40/3XL_WAREHOUSE\", 0) AS WAREHOUSE_INVENTORY, COALESCE(\"40/3XL_OMNI\", 0) AS OMNI_INVENTORY, COALESCE(\"40/3XL_QUICK\", 0) AS QUICK_INVENTORY FROM source_inventory UNION ALL SELECT SKU_GROUP, \'ALL WAREHOUSES\', \'42/4XL\', CATEGORY_NAME, COALESCE(\"42/4XL_WAREHOUSE\", 0), COALESCE(\"42/4XL_OMNI\", 0), COALESCE(\"42/4XL_QUICK\", 0) FROM source_inventory UNION ALL SELECT SKU_GROUP, \'ALL WAREHOUSES\', \'44/5XL\', CATEGORY_NAME, COALESCE(\"44/5XL_WAREHOUSE\", 0), COALESCE(\"44/5XL_OMNI\", 0), COALESCE(\"44/5XL_QUICK\", 0) FROM source_inventory UNION ALL SELECT SKU_GROUP, \'ALL WAREHOUSES\', \'46/6XL\', CATEGORY_NAME, COALESCE(\"46/6XL_WAREHOUSE\", 0), COALESCE(\"46/6XL_OMNI\", 0), COALESCE(\"46/6XL_QUICK\", 0) FROM source_inventory UNION ALL SELECT SKU_GROUP, \'ALL WAREHOUSES\', \'48/7XL\', CATEGORY_NAME, COALESCE(\"48/7XL_WAREHOUSE\", 0), COALESCE(\"48/7XL_OMNI\", 0), COALESCE(\"48/7XL_QUICK\", 0) FROM source_inventory UNION ALL SELECT SKU_GROUP, \'ALL WAREHOUSES\', \'50/8XL\', CATEGORY_NAME, COALESCE(\"50/8XL_WAREHOUSE\", 0), COALESCE(\"50/8XL_OMNI\", 0), COALESCE(\"50/8XL_QUICK\", 0) FROM source_inventory ), inventory_calculated AS ( SELECT SKU_GROUP, WAREHOUSE, SIZE_LABEL, CATEGORY_NAME, WAREHOUSE_INVENTORY, OMNI_INVENTORY, QUICK_INVENTORY, WAREHOUSE_INVENTORY + OMNI_INVENTORY + QUICK_INVENTORY AS WAREHOUSE_OMNI_QUICK_INVENTORY, OMNI_INVENTORY + QUICK_INVENTORY AS OMNI_QUICK_INVENTORY FROM size_level ), cut_size_status AS ( SELECT SKU_GROUP, CASE WHEN MAX(IFF( SIZE_LABEL = \'40/3XL\', WAREHOUSE_INVENTORY, 0 )) = 0 OR MAX(IFF( SIZE_LABEL = \'42/4XL\', WAREHOUSE_INVENTORY, 0 )) = 0 OR MAX(IFF( SIZE_LABEL = \'44/5XL\', WAREHOUSE_INVENTORY, 0 )) = 0 OR MAX(IFF( SIZE_LABEL = \'46/6XL\', WAREHOUSE_INVENTORY, 0 )) = 0 THEN \'CUT SIZE\' ELSE \'FULL SIZE\' END AS WAREHOUSE_CUT_SIZE_STATUS, CASE WHEN MAX(IFF( SIZE_LABEL = \'40/3XL\', WAREHOUSE_OMNI_QUICK_INVENTORY, 0 )) = 0 OR MAX(IFF( SIZE_LABEL = \'42/4XL\', WAREHOUSE_OMNI_QUICK_INVENTORY, 0 )) = 0 OR MAX(IFF( SIZE_LABEL = \'44/5XL\', WAREHOUSE_OMNI_QUICK_INVENTORY, 0 )) = 0 OR MAX(IFF( SIZE_LABEL = \'46/6XL\', WAREHOUSE_OMNI_QUICK_INVENTORY, 0 )) = 0 THEN \'CUT SIZE\' ELSE \'FULL SIZE\' END AS WAREHOUSE_OMNI_QUICK_CUT_SIZE_STATUS, CASE WHEN MAX(IFF( SIZE_LABEL = \'40/3XL\', OMNI_QUICK_INVENTORY, 0 )) = 0 OR MAX(IFF( SIZE_LABEL = \'42/4XL\', OMNI_QUICK_INVENTORY, 0 )) = 0 OR MAX(IFF( SIZE_LABEL = \'44/5XL\', OMNI_QUICK_INVENTORY, 0 )) = 0 OR MAX(IFF( SIZE_LABEL = \'46/6XL\', OMNI_QUICK_INVENTORY, 0 )) = 0 THEN \'CUT SIZE\' ELSE \'FULL SIZE\' END AS OMNI_QUICK_CUT_SIZE_STATUS FROM inventory_calculated GROUP BY SKU_GROUP ) SELECT d.SKU_GROUP, d.WAREHOUSE, d.SIZE_LABEL, d.CATEGORY_NAME, d.WAREHOUSE_INVENTORY, d.OMNI_INVENTORY, d.QUICK_INVENTORY, d.WAREHOUSE_OMNI_QUICK_INVENTORY, d.OMNI_QUICK_INVENTORY, s.WAREHOUSE_CUT_SIZE_STATUS, s.OMNI_QUICK_CUT_SIZE_STATUS, s.WAREHOUSE_OMNI_QUICK_CUT_SIZE_STATUS FROM inventory_calculated d LEFT JOIN cut_size_status s ON d.SKU_GROUP = s.SKU_GROUP ORDER BY d.WAREHOUSE, d.SKU_GROUP, d.SIZE_LABEL;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            